# правки Ш87, Ш89–Ш91 (gift item, the help of the ball game, «Точно сдаться», wall label): new keys → keys.json + src/tr18.txt
import json, re
KJ = 'tools/i18n/keys.json'
keys = json.load(open(KJ, encoding='utf8'))
LET = 'A-Za-zА-Яа-яЁёІіЇїЄєÀ-ÿ'
CORE = re.compile(rf'^([^{LET}{{}}\d]*)([\s\S]*?)([^{LET}{{}}\d]*)$')
def key(t):  # the same as i18n.ts: the core without edge marks, numbers → {}
    b = re.sub(r'\s+', ' ', CORE.match(t).group(2)).strip()
    return re.sub(r'\d+(?:[.,]\d+)?', '{}', b)
